mapper.select:
SELECT * FROM ( SELECT C.COMPANION_NO, C.TITLE, C.CONTENT, C.IMAGE_URL, C.TRAVEL_DATE, C.MAX_MEMBERS, C.TAGS, C.STATUS, C.MEMBER_NO, C.LATITUDE, C.LONGITUDE, C.PLACE_NAME, TO_CHAR(C.CREATED_AT, 'YYYY-MM-DD') AS CREATED_AT, M.NICKNAME AS AUTHOR_NICKNAME, M.PROFILE_IMAGE AS AUTHOR_PROFILE, M.AGE_RANGE AS AUTHOR_AGE_RANGE, (SELECT COUNT(*) FROM COMPANION_JOIN J WHERE J.COMPANION_NO = C.COMPANION_NO AND J.STATUS IN ('W', 'A') ) AS CURRENT_MEMBERS, ROW_NUMBER() OVER (ORDER BY C.CREATED_AT DESC) AS RN FROM COMPANION_BOARD C JOIN MEMBER M ON C.MEMBER_NO = M.MEMBER_NO WHERE C.STATUS = 'Y'
AND C.TAGS LIKE '%' || #{tag} || '%'
) WHERE RN BETWEEN #{offset} + 1 AND #{offset} + #{limit}

mapper.insert:
INSERT INTO COMPANION_BOARD (
    COMPANION_NO, TITLE, CONTENT, IMAGE_URL,
    TRAVEL_DATE, MAX_MEMBERS, TAGS, MEMBER_NO, CONTENT_IMAGES,
    LATITUDE, LONGITUDE, PLACE_NAME
) VALUES (
    SEQ_COMPANION_NO.NEXTVAL,
    #{title}, #{content}, #{imageUrl},
    #{travelDate}, #{maxMembers}, #{tags}, #{memberNo}, #{contentImages},
    #{latitude}, #{longitude}, #{placeName}
)

mapper.update:
UPDATE COMPANION_BOARD
SET STATUS = 'N', UPDATED_AT = SYSDATE
WHERE COMPANION_NO = #{companionNo}
  AND MEMBER_NO = #{memberNo}

mapper.insert:
INSERT INTO COMPANION_JOIN (
    JOIN_NO, COMPANION_NO, MEMBER_NO
) VALUES (
    SEQ_COMPANION_JOIN_NO.NEXTVAL,
    #{companionNo}, #{memberNo}
)

mapper.update:
UPDATE COMPANION_JOIN
SET STATUS = 'C'
WHERE COMPANION_NO = #{companionNo}
  AND MEMBER_NO = #{memberNo}
  AND STATUS IN ('W', 'A')

UPDATE COMPANION_JOIN
SET STATUS = #{status}
WHERE JOIN_NO = #{joinNo}
  AND COMPANION_NO IN (
      SELECT COMPANION_NO
      FROM COMPANION_BOARD
      WHERE MEMBER_NO = #{memberNo}
  )

mapper.select:
SELECT COUNT(*)
FROM COMPANION_JOIN
WHERE COMPANION_NO = #{companionNo}
  AND MEMBER_NO = #{memberNo}
  AND STATUS IN ('W', 'A')
